#ifndef CAPSTONE_DIET
static char *printAliasInstr(MCInst *MI, SStream *OS);
#endif
static void printInstruction(MCInst *MI, SStream *O);

void X86_Intel_printInst(MCInst *MI, SStream *O, void *Info)
{
#ifndef CAPSTONE_DIET
        char *mnem;
#endif
        x86_reg reg, reg2;
        enum cs_ac_type access1, access2;

        // perhaps this instruction does not need printer
        if (MI->assembly[0]) {
                strncpy(O->buffer, MI->assembly, sizeof(O->buffer));
                return;
        }

#ifndef CAPSTONE_DIET
        // Try to print any aliases first.
        mnem = printAliasInstr(MI, O);
        if (mnem)
                cs_mem_free(mnem);
        else
#endif
        {
                X86_lockrep(MI, O);
                printInstruction(MI, O);
        }

        reg = X86_insn_reg_intel(MCInst_getOpcode(MI), &access1);
        if (MI->csh->detail) {
#ifndef CAPSTONE_DIET
                uint8_t access[6] = {0};
#endif

                // first op can be embedded in the asm by llvm.
                // so we have to add the missing register as the first operand
                if (reg) {
                        // shift all the ops right to leave 1st slot for this new register op
                        memmove(&(MI->flat_insn->detail->x86.operands[1]), &(MI->flat_insn->detail->x86.operands[0]),
                                        sizeof(MI->flat_insn->detail->x86.operands[0]) * (ARR_SIZE(MI->flat_insn->detail->x86.operands) - 1));
                        MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
                        MI->flat_insn->detail->x86.operands[0].reg = reg;
                        MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
                        MI->flat_insn->detail->x86.operands[0].access = access1;
                        MI->flat_insn->detail->x86.op_count++;
                } else {
                        if (X86_insn_reg_intel2(MCInst_getOpcode(MI), &reg, &access1, &reg2, &access2)) {
                                MI->flat_insn->detail->x86.operands[0].type = X86_OP_REG;
                                MI->flat_insn->detail->x86.operands[0].reg = reg;
                                MI->flat_insn->detail->x86.operands[0].size = MI->csh->regsize_map[reg];
                                MI->flat_insn->detail->x86.operands[0].access = access1;
                                MI->flat_insn->detail->x86.operands[1].type = X86_OP_REG;
                                MI->flat_insn->detail->x86.operands[1].reg = reg2;
                                MI->flat_insn->detail->x86.operands[1].size = MI->csh->regsize_map[reg2];
                                MI->flat_insn->detail->x86.operands[1].access = access2;
                                MI->flat_insn->detail->x86.op_count = 2;
                        }
                }

#ifndef CAPSTONE_DIET
                get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                MI->flat_insn->detail->x86.operands[0].access = access[0];
                MI->flat_insn->detail->x86.operands[1].access = access[1];
#endif
        }

        if (MI->op1_size == 0 && reg)
                MI->op1_size = MI->csh->regsize_map[reg];
}

/// printPCRelImm - This is used to print an immediate value that ends up
/// being encoded as a pc-relative value.
static void printPCRelImm(MCInst *MI, unsigned OpNo, SStream *O)
{
        MCOperand *Op = MCInst_getOperand(MI, OpNo);
        if (MCOperand_isImm(Op)) {
                int64_t imm = MCOperand_getImm(Op) + MI->flat_insn->size + MI->address;
                uint8_t opsize = X86_immediate_size(MI->Opcode, NULL);

                // truncat imm for non-64bit
                if (MI->csh->mode != CS_MODE_64) {
                        imm = imm & 0xffffffff;
                }

                printImm(MI, O, imm, true);

                if (MI->csh->detail) {
#ifndef CAPSTONE_DIET
                        uint8_t access[6];
#endif

                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
                        // if op_count > 0, then this operand's size is taken from the destination op
                        if (MI->flat_insn->detail->x86.op_count > 0)
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->flat_insn->detail->x86.operands[0].size;
                        else if (opsize > 0)
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
                        else
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;

#ifndef CAPSTONE_DIET
                        get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
#endif

                        MI->flat_insn->detail->x86.op_count++;
                }

                if (MI->op1_size == 0)
                        MI->op1_size = MI->imm_size;
        }
}

static void printOperand(MCInst *MI, unsigned OpNo, SStream *O)
{
        MCOperand *Op  = MCInst_getOperand(MI, OpNo);

        if (MCOperand_isReg(Op)) {
                unsigned int reg = MCOperand_getReg(Op);

                printRegName(O, reg);
                if (MI->csh->detail) {
                        if (MI->csh->doing_mem) {
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.base = X86_register_map(reg);
                        } else {
#ifndef CAPSTONE_DIET
                                uint8_t access[6];
#endif

                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_REG;
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].reg = X86_register_map(reg);
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->csh->regsize_map[X86_register_map(reg)];

#ifndef CAPSTONE_DIET
                                get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
#endif

                                MI->flat_insn->detail->x86.op_count++;
                        }
                }

                if (MI->op1_size == 0)
                        MI->op1_size = MI->csh->regsize_map[X86_register_map(reg)];
        } else if (MCOperand_isImm(Op)) {
                uint8_t encsize;
                int64_t imm = MCOperand_getImm(Op);
                uint8_t opsize = X86_immediate_size(MCInst_getOpcode(MI), &encsize);

                if (opsize == 1)    // print 1 byte immediate in positive form
                        imm = imm & 0xff;

                // printf(">>> id = %u\n", MI->flat_insn->id);
                switch(MI->flat_insn->id) {
                        default:
                                printImm(MI, O, imm, MI->csh->imm_unsigned);
                                break;

                        case X86_INS_MOVABS:
                        case X86_INS_MOV:
                                // do not print number in negative form
                                printImm(MI, O, imm, true);
                                break;

                        case X86_INS_IN:
                        case X86_INS_OUT:
                        case X86_INS_INT:
                                // do not print number in negative form
                                imm = imm & 0xff;
                                printImm(MI, O, imm, true);
                                break;

                        case X86_INS_LCALL:
                        case X86_INS_LJMP:
                        case X86_INS_JMP:
                                // always print address in positive form
                                if (OpNo == 1) {        // ptr16 part
                                        imm = imm & 0xffff;
                                        opsize = 2;
                                } else
                                        opsize = 4;
                                printImm(MI, O, imm, true);
                                break;

                        case X86_INS_AND:
                        case X86_INS_OR:
                        case X86_INS_XOR:
                                // do not print number in negative form
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        printImm(MI, O, imm, true);
                                else {
                                        imm = arch_masks[opsize? opsize : MI->imm_size] & imm;
                                        printImm(MI, O, imm, true);
                                }
                                break;

                        case X86_INS_RET:
                        case X86_INS_RETF:
                                // RET imm16
                                if (imm >= 0 && imm <= HEX_THRESHOLD)
                                        printImm(MI, O, imm, true);
                                else {
                                        imm = 0xffff & imm;
                                        printImm(MI, O, imm, true);
                                }
                                break;
                }

                if (MI->csh->detail) {
                        if (MI->csh->doing_mem) {
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].mem.disp = imm;
                        } else {
#ifndef CAPSTONE_DIET
                                uint8_t access[6];
#endif

                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].type = X86_OP_IMM;
                                if (opsize > 0) {
                                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = opsize;
                                        MI->flat_insn->detail->x86.encoding.imm_size = encsize;
                                } else if (MI->flat_insn->detail->x86.op_count > 0) {
                                        if (MI->flat_insn->id != X86_INS_LCALL && MI->flat_insn->id != X86_INS_LJMP) {
                                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size =
                                                        MI->flat_insn->detail->x86.operands[0].size;
                                        } else
                                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
                                } else
                                        MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].size = MI->imm_size;
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].imm = imm;

#ifndef CAPSTONE_DIET
                                get_op_access(MI->csh, MCInst_getOpcode(MI), access, &MI->flat_insn->detail->x86.eflags);
                                MI->flat_insn->detail->x86.operands[MI->flat_insn->detail->x86.op_count].access = access[MI->flat_insn->detail->x86.op_count];
#endif

                                MI->flat_insn->detail->x86.op_count++;
                        }
                }
        }
}
